 ptr,_:=syscall.UTF16PtrFromString(`\\.\OpenG104`);h,e:=syscall.CreateFile(ptr,syscall.GENERIC_READ|syscall.GENERIC_WRITE,0,nil,syscall.OPEN_EXISTING,0,0);must(e);defer syscall.CloseHandle(h)
 b,e:=op(h,0x226880,80,0);must(e);s,e:=decodeStatus(b);must(e);result["status_before"]=s;if mode=="status"{result["ok"]=true;return};if s["kernel_build"]!=uint32(26300)||s["processors"]!=uint32(8)||s["IRQL"]!=uint32(0)||s["firmware_match"]!=uint32(1)||s["firmware_bytes"]!=uint32(576){panic("qualified platform required")};if mode=="read"&&(s["attempts"]!=uint32(0)||s["map_calls"]!=uint32(0)){panic("owner consumed: observe frozen result")}
